package com.billbull.backend.pos; import com.billbull.backend.inventory.product.ProductService; import com.billbull.backend.security.BranchContextHolder; import org.junit.jupiter.api.Test; import org.springframework.beans.factory.annotation.Autowired; import org.springframework.boot.test.context.SpringBootTest; import org.springframework.transaction.annotation.Transactional; import java.util.List; import java.util.Map; import static org.assertj.core.api.Assertions.assertThat; @SpringBootTest public class PosStockDisplayRuntimeAuditTest { @Autowired private ProductService productService; @Test @Transactional public void verifyMissingBranchSafety() { BranchContextHolder.clear(); Map<Long, Integer> result = productService.batchBranchScopedStockForPos(List.of(9999L)); assertThat(result.getOrDefault(9999L, 0)).isEqualTo(0); System.out.println("VERIFIED: Missing POS Branch Safety returns 0 stock, not company-wide stock."); } }
